\echo '--- administração principal e embaixadoras (somente fixtures locais)'
set role anon;
select tst.bloqueia($$select public.mvp_admin_access()$$,'visitante não consulta funções administrativas');
select tst.bloqueia($$select public.mvp_admin_profiles()$$,'visitante não lê perfis para curadoria');
reset role;
set role authenticated; select set_config('request.jwt.claim.sub', :'u1', false);
select tst.ok(not (public.mvp_admin_access()->>'principal')::boolean,'participante não é administradora principal');
select tst.bloqueia($$select public.mvp_admin_members('')$$,'participante não consulta membros administrativos');
select tst.bloqueia($$select public.mvp_admin_profiles()$$,'participante não avalia perfis');
select tst.bloqueia($$select public.mvp_admin_reports()$$,'participante não lê denúncias administrativas');
select tst.bloqueia($$select public.mvp_bootstrap_principal(auth.uid())$$,'participante não faz bootstrap da própria conta');
select tst.bloqueia($$insert into public.roles(user_id,role) values(auth.uid(),'administradora')$$,'participante não se promove editando roles');
select tst.bloqueia($$insert into public.ambassador_permissions(user_id,granted_by,review_profiles) values(auth.uid(),auth.uid(),true)$$,'participante não insere autorização de embaixadora');
select tst.bloqueia(format('select public.mvp_job_status(%L)', :'queued'),'participante não consulta job de outra pessoa');
reset role;
set role authenticated;select set_config('request.jwt.claim.sub', :cur, false);
select tst.ok(public.is_curadora(),'acesso legado permanece até bootstrap autorizado');
select tst.bloqueia(format('select public.mvp_manage_ambassador(%L,true,false,true)', :'u1'),'papel legado sozinho não concede embaixadoras');
reset role;
set role service_role;
select public.mvp_bootstrap_principal(:cur::uuid);
select tst.bloqueia(format('select public.mvp_bootstrap_principal(%L)', :'u2'),'bootstrap não substitui a administradora principal');
reset role;
set role authenticated;select set_config('request.jwt.claim.sub', :cur, false);
select tst.ok((public.mvp_admin_access()->>'principal')::boolean,'UUID verificado recebe função principal');
select public.mvp_manage_ambassador(:'u1',true,false,true);
select public.mvp_manage_ambassador(:'u2',false,true,true);
select tst.bloqueia($$select public.mvp_manage_ambassador(auth.uid(),true,true,false)$$,'gerência de embaixadoras não altera a administradora principal');
select tst.ok(jsonb_array_length(public.mvp_admin_members(''))>=2,'administradora consulta participantes e permissões');
select tst.ok(jsonb_array_length(public.mvp_admin_audit())>=3,'bootstrap e concessões ficam auditados');
select set_config('request.jwt.claim.sub', :'u1', false);
select tst.ok(not public.is_curadora() and public.mvp_can_review_profiles(),'embaixadora pode avaliar sem privilégios legados amplos');
select tst.ok(jsonb_typeof(public.mvp_admin_profiles('aprovado'))='array','embaixadora lê somente dados de revisão sem contatos');
select public.mvp_admin_review(:'u3','pausado');
select tst.bloqueia($$select public.mvp_admin_review(auth.uid(),'aprovado')$$,'embaixadora não aprova a si mesma');
select tst.bloqueia($$select public.mvp_admin_reports()$$,'embaixadora de perfis não trata denúncias');
select tst.bloqueia($$select public.mvp_metrics()$$,'embaixadora não consulta indicadores sensíveis');
select tst.bloqueia(format('select public.mvp_manage_ambassador(%L,true,true,true)', :'u3'),'embaixadora não cria outras embaixadoras');
select tst.bloqueia($$select public.mvp_admin_audit()$$,'embaixadora não consulta auditoria de gestão de papéis');
select tst.ok((select count(*) from public.professional_contacts where profile_id=:'u2')=0,'embaixadora não lê contatos privados de outra participante');
select set_config('request.jwt.claim.sub', :'u2', false);
select tst.ok(not public.mvp_can_review_profiles() and public.mvp_can_handle_reports(),'embaixadora de denúncias não herda revisão de perfis');
select tst.ok(jsonb_typeof(public.mvp_admin_reports())='array','embaixadora de denúncias acessa somente sua atribuição');
select tst.bloqueia($$select public.mvp_admin_profiles()$$,'embaixadora de denúncias não consulta curadoria de perfis');
select set_config('request.jwt.claim.sub', :cur, false);
select public.mvp_manage_ambassador(:'u1',false,false,false);
select tst.ok(jsonb_array_length(public.mvp_admin_audit())>=4,'revogação é registrada em auditoria');
select set_config('request.jwt.claim.sub', :'u1', false);
select tst.ok(not public.mvp_can_review_profiles() and not public.is_curadora(),'revogação remove privilégios imediatamente no banco');
select tst.bloqueia($$select public.mvp_admin_profiles()$$,'conta revogada não usa RPC administrativa em sessão existente');
select tst.bloqueia($$select public.mvp_admin_review('10000000-0000-0000-0000-000000000003','aprovado')$$,'conta revogada não altera status de outra pessoa');
reset role;
-- 030: painel por permissão, busca com e-mail mascarado e acessos por pessoa.
update auth.users set email='ka.teste@exemplo.invalid' where id=:'u3';
set role authenticated;select set_config('request.jwt.claim.sub', :cur, false);
select tst.ok(public.mvp_admin_search('')='[]'::jsonb and public.mvp_admin_search('k')='[]'::jsonb,'nada é listado antes da busca');
select public.mvp_admin_search('ka.teste') as busca \gset
select tst.ok(jsonb_array_length(:'busca'::jsonb)=1 and :'busca'::jsonb->0->>'email'='ka***@exemplo.invalid','busca por e-mail devolve o e-mail mascarado');
select tst.ok(position('ka.teste@' in :'busca')=0,'a busca nunca devolve o e-mail completo');
select tst.ok(jsonb_array_length(public.mvp_admin_search('%'))=0,'curinga do LIKE não lista todo mundo');
select tst.ok(jsonb_array_length(public.mvp_admin_search('participante'))<=10,'no máximo 10 resultados');
select public.mvp_salvar_acessos(:'u3',false,true,false,false,false);
select tst.ok(public.mvp_admin_ambassadors()::text like '%ka***@exemplo.invalid%' and public.mvp_admin_ambassadors()::text not like '%ka.teste@%','lista de embaixadoras com e-mail mascarado');
select tst.ok((public.mvp_admin_audit()->0->'permissions'->>'avaliar_perfis')='true' and public.mvp_admin_audit()->0->>'target_name' is not null,'concessão auditada com as cinco permissões');
select tst.ok((public.mvp_admin_access()->>'ver_ia_automacoes')::boolean and (public.mvp_admin_access()->>'ver_feedback')::boolean and (public.mvp_admin_access()->>'ver_visao_geral')::boolean,'a principal tem todas as permissões');
select set_config('request.jwt.claim.sub', :'u3', false);
select tst.ok(public.mvp_can_review_profiles() and not (public.mvp_admin_access()->>'ver_visao_geral')::boolean,'embaixadora só com Avaliar perfis');
select tst.bloqueia($$select public.mvp_metrics()$$,'embaixadora só com Avaliar perfis não chama mvp_metrics');
select tst.bloqueia($$select public.mvp_feedback_metrics(current_date)$$,'embaixadora só com Avaliar perfis não chama as métricas do feedback');
select tst.bloqueia($$select public.mvp_conversation_metrics()$$,'embaixadora só com Avaliar perfis não vê a avaliação das conversas');
select tst.bloqueia($$select public.mvp_ai_metrics()$$,'embaixadora só com Avaliar perfis não vê IA e automações');
select tst.ok((select count(*) from public.feedback)=0,'embaixadora só com Avaliar perfis não lê feedback');
select tst.ok((select count(*) from public.conversation_jobs)=0 and (select count(*) from public.conversation_expiry_runs)=0,'nem execuções da IA nem a rotina diária (exportações)');
select tst.ok(not (public.mvp_admin_counts() ? 'feedback') and public.mvp_admin_counts() ? 'perfis','contadores só das abas permitidas');
select tst.ok(not exists(select 1 from jsonb_array_elements(public.mvp_admin_profiles('aprovado')) e where e->>'status'<>'pendente'),'aba Perfis só traz os que aguardam aprovação');
select tst.bloqueia($$select public.mvp_admin_search('ka')$$,'embaixadora não busca pessoas');
select tst.bloqueia(format('select public.mvp_salvar_acessos(%L,true,true,true,true,true)', :'u2'),'embaixadora não concede acessos');
select tst.bloqueia(format('select public.mvp_salvar_acessos(%L,true,true,true,true,true)', :'u3'),'embaixadora não se dá acessos');
select tst.bloqueia($$select public.mvp_admin_ambassadors()$$,'embaixadora não lista embaixadoras');
select set_config('request.jwt.claim.sub', :cur, false);
select public.mvp_salvar_acessos(:'u3',false,false,false,true,false);
select set_config('request.jwt.claim.sub', :'u3', false);
select tst.ok((select count(*) from public.feedback)>0 and jsonb_typeof(public.mvp_feedback_metrics(current_date))='object','com Ver feedback, lê o feedback');
select tst.bloqueia($$select public.mvp_metrics()$$,'Ver feedback não abre a visão geral');
select tst.bloqueia($$select public.mvp_admin_profiles()$$,'acesso trocado: Avaliar perfis saiu na hora');
select set_config('request.jwt.claim.sub', :cur, false);
select public.mvp_salvar_acessos(:'u3',false,false,false,false,false);
select tst.ok(public.mvp_admin_ambassadors()::text not like '%ka***@%' and (public.mvp_admin_search('ka.teste')->0->>'ver_feedback')='false','nenhuma caixa marcada revoga o acesso');
select tst.bloqueia($$select public.mvp_salvar_acessos(auth.uid(),true,true,true,true,true)$$,'a principal não altera o próprio acesso');
reset role;
select tst.ok(not exists(select 1 from public.ambassador_permissions where user_id=:'u3') and not exists(select 1 from public.roles where user_id=:'u3' and role='embaixadora'),'revogação apaga a permissão e o papel');
set role anon;
select tst.bloqueia($$select public.mvp_admin_search('ka')$$,'visitante não busca pessoas');
select tst.bloqueia($$select public.mvp_mascara_email('a@b.c')$$,'função de máscara não é pública');
reset role;
-- Metadados de usuário não participam de nenhuma verificação de privilégios.
update auth.users set raw_user_meta_data='{"role":"administradora","is_admin":true}' where id=:'u3';
set role authenticated;select set_config('request.jwt.claim.sub', :'u3', false);
select tst.ok(not (public.mvp_admin_access()->>'principal')::boolean,'metadados editáveis não concedem administração');
select tst.bloqueia($$select public.mvp_admin_members('')$$,'metadados falsos não liberam lista de membros');
reset role;
